import { registerWebComponents } from '@domg-wc/common';
import { VlInputFieldComponent } from '@domg-wc/components/form';

registerWebComponents([VlInputFieldComponent]);

// vl-change volgt op elke wijziging van de waarde, ook door code; vl-input enkel op invoer door de gebruiker.
// event.detail.value is de nieuwe waarde.
document.querySelector('vl-input-field').addEventListener('vl-input', (event) => {
    console.log(event.detail.value);
});
